def second_largest(xs):
    """
    Return the second largest distinct value from the iterable `xs`.
    If fewer than two distinct values exist, return None.
    """
    # Use a set to extract unique values
    try:
        unique = set(xs)
    except TypeError:
        # If elements are unhashable (e.g., lists), fall back to a list of uniques
        unique = []
        for v in xs:
            if v not in unique:
                unique.append(v)

    if len(unique) < 2:
        return None

    # Find the largest element
    largest = max(unique)
    # Remove it and find the next largest
    unique.discard(largest) if hasattr(unique, 'discard') else unique.remove(largest)
    return max(unique)
